from final_http import *
b=director();tag='RECETTE-'+str(int(time.time()));state={'tag':tag}
def save(): (OUT/'mutation-state.json').write_text(json.dumps(state),encoding='utf-8')
def ident(table,pk,column,value):return db('SELECT '+pk+' FROM '+table+' WHERE '+column+'='+literal(value)+' ORDER BY '+pk+' DESC LIMIT 1')
b.post('EquipeServlet',{'nom':tag,'description':'Équipe de recette finale','date_creation':'2026-09-10'});state['team']=ident('equipe','id','nom',tag);save()
event={'titre':tag,'type_event':'WORKSHOP','date_event':'2026-09-15T10:00','date_fin':'2026-09-15T12:00','lieu':'Salle recette','edition':'2026','description':'Recette finale HTTP'}
b.post('AjouterEvenementServlet',event);state['event']=ident('evenement','id_event','titre',tag);save()
b.post('AjouterEvenementServlet',dict(event,id=state['event'],description='Modification vérifiée'))
b.post('AjouterEvenementServlet',{'action':'participant','id':state['event'],'membre_id':'4','responsabilite':'ORGANISATEUR'})
b.post('AjouterPublicationServlet',{'titre':tag+' publication','auteurs':'Directeur recette','annee':'2026','journal_conference':'Revue recette','equipe_id':state['team'],'doi':'10.1234/recette'})
state['publication']=ident('publication','id_pub','titre',tag+' publication');save()
code,body,_=b.upload('DocumentServlet',{'titre':tag+' document','type_doc':'RAPPORT','evenement_id':state['event']},'../../recette.jsp')
check(code==200 and 'Opération enregistrée avec succès.' in body,'upload PDF avec nom de fichier hostile neutralisé')
state['document']=ident('document','id_doc','titre',tag+' document');save()
r=b.opener.open(BASE+'DownloadServlet?id='+state['document']);check(r.status==200 and r.read().startswith(b'%PDF-'),'téléchargement PDF réel')
check(db('SELECT nom_fichier FROM document WHERE id_doc='+state['document']).endswith('.pdf'),'nom stocké UUID PDF')
code,body,_=b.upload('DocumentServlet',{'titre':tag+' document v2','type_doc':'RAPPORT','precedent_id':state['document']})
check(code==200 and 'Opération enregistrée' in body,'version document ajoutée');check(db('SELECT version FROM document WHERE precedent_id='+state['document'])=='2','ancienne version conservée')
code,body,_=b.upload('DocumentServlet',{'titre':tag+' invalide','type_doc':'RAPPORT'},content=b'<script>bad</script>');check('Document PDF requis' in body,'contenu non PDF refusé')
b.post('ReunionServlet',{'titre':tag+' réunion','date_reunion':'2026-09-16T10:00','lieu':'Salle recette','ordre_du_jour':'Recette finale','contenu':'Validation'})
state['meeting']=ident('reunion','id_reunion','titre',tag+' réunion');save()
b.post('ReunionServlet',{'action':'participant','id':state['meeting'],'membre_id':'4'})
code,body,_=b.upload('ReunionServlet',{'action':'pv','titre':tag+' PV','reunion_id':state['meeting']});check('Opération enregistrée' in body,'PV upload réunion')
check(db('SELECT COUNT(*) FROM document WHERE reunion_id='+state['meeting'])=='1','PV rattaché aux archives')
b.post('ConventionServlet',{'section':'partenaires','nom_institution':tag,'nom':'Partenaire recette','pays':'Maroc'})
state['partner']=ident('partenaire','id_partenaire','nom_institution',tag);save()
b.post('ConventionServlet',{'section':'conventions','titre':tag+' convention','partenaire_id':state['partner'],'date_debut':'2026-01-01','date_fin':'2026-12-31','description':'Recette','document_id':state['document']})
state['convention']=ident('convention','id','titre',tag+' convention');save()
b.post('ConventionServlet',{'section':'activites','titre':tag+' activité','convention_id':state['convention'],'date_activite':'2026-09-15','description':'Recette'})
b.post('AjouterMaterielServlet',{'action':'stock','nom':tag+' matériel','etat':'DISPONIBLE'});state['material']=ident('materiel','id','nom',tag+' matériel');save()
b.post('AjouterMaterielServlet',{'action':'arrivage','materiel_id':state['material'],'quantite':'3'})
b.post('AjouterMaterielServlet',{'action':'demander','materiel_id':state['material'],'quantite':'2','description':'Besoin de recette finale'})
state['request']=db('SELECT id_demande_mat FROM demande_materiel WHERE materiel_id='+state['material']+' ORDER BY id_demande_mat DESC LIMIT 1');save()
b.post('AjouterMaterielServlet',{'action':'traiter','id':state['request'],'decision':'ACCEPTEE'})
b.post('AjouterMaterielServlet',{'action':'traiter','id':state['request'],'decision':'LIVREE'})
check(db('SELECT quantite FROM materiel WHERE id='+state['material'])=='1','stock décrémenté après livraison HTTP')
check(db('SELECT COUNT(*) FROM distribution_materiel WHERE demande_id='+state['request'])=='1','distribution historisée')
code,body,_=b.post('AjouterMaterielServlet',{'action':'traiter','id':state['request'],'decision':'LIVREE'},expect=False);check('Transition impossible' in body,'double livraison refusée')
code,body,_=b.post('AjouterMaterielServlet',{'action':'distribuer','materiel_id':state['material'],'membre_id':'4','quantite':'10'},expect=False);check('insuffisante' in body,'stock insuffisant refusé')
for page in ['recherche.jsp?q='+tag,'rapport.jsp?annee=2026','calendrier.jsp']:
 code,body,_=b.req(page);check(code==200 and tag in body,page+' données réelles présentes')
code,body,_=b.req('rapport.jsp?annee=2025');check(tag not in body.split('<main',1)[-1],'rapport autre année exclut activité')
b.post('AjouterEvenementServlet',{'action':'archive','id':state['event']})
b.post('ConventionServlet',{'action':'archive','section':'conventions','id':state['convention']})
b.post('ReunionServlet',{'action':'archive','id':state['meeting']})
check(db('SELECT COUNT(*) FROM evenement WHERE id_event='+state['event'])=='1','archivage conserve événement')
(OUT/'mutations-results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2),encoding='utf-8')
